CREATE OR REPLACE FUNCTION panas_accounting_balanced(data jsonb) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$ SELECT CASE WHEN jsonb_typeof(data)='array' THEN (SELECT count(*)>=2 AND count(DISTINCT e->>'account')=count(*) AND bool_and(coalesce(jsonb_typeof(e->'account')='string' AND length(e->>'account') BETWEEN 1 AND 100 AND (e->>'amountAtomic') ~ '^-?(0|[1-9][0-9]{0,29})$',false)) AND sum(CASE WHEN (e->>'amountAtomic') ~ '^-?(0|[1-9][0-9]{0,29})$' THEN (e->>'amountAtomic')::numeric ELSE NULL END)=0 FROM jsonb_array_elements(data) e) ELSE false END $$;
